// Turns openapi/*.json (written by the backend's ApiExporter) into src/generated/*.ts.
// `--check` writes nothing and fails if a generated file would change.
import { readdir, readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");
const header = "// <auto-generated> Edit the backend and run scripts/generate.\n";

const documents = (await readdir(join(root, "openapi"))).filter((f) => f.endsWith(".json")).sort();
const outOfDate = [];
for (const file of documents) {
  const key = file.replace(/\.json$/, "");
  const ast = await openapiTS(new URL(`file://${join(root, "openapi", file)}`), { alphabetize: true });
  const content = header + astToString(ast).replace(/\r\n/g, "\n").trimEnd() + "\n";
  const target = join(root, "src", "generated", `${key}.ts`);
  const current = await readFile(target, "utf8").catch(() => null);
  if (current === content) continue;
  outOfDate.push(relative(join(root, "..", "..", ".."), target));
  if (!check) {
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, content);
  }
}

// One typed client per service, created in src/clients.ts (generated: the list of services comes from the documents).
const names = documents.map((f) => f.replace(/\.json$/, ""));
const pascal = (key) => key.replace(/(^|-)([a-z])/g, (_, __, c) => c.toUpperCase());
const clients =
  header +
  names.map((n) => `import type { paths as ${pascal(n)}Paths } from "./generated/${n}";`).join("\n") +
  "\n\n" +
  "/** The path maps of every service, by service key. */\n" +
  "export interface ServicePaths {\n" +
  names.map((n) => `  "${n}": ${pascal(n)}Paths;`).join("\n") +
  "\n}\n";
const clientsTarget = join(root, "src", "service-paths.ts");
const currentClients = await readFile(clientsTarget, "utf8").catch(() => null);
if (currentClients !== clients) {
  outOfDate.push(relative(join(root, "..", "..", ".."), clientsTarget));
  if (!check) await writeFile(clientsTarget, clients);
}

for (const path of outOfDate) console.log(`${check ? "out of date" : "updated"}: ${path}`);
if (check && outOfDate.length > 0) process.exit(1);
